-- GENERATED by tools/make_tools.py from src/FSUtility.lua.
-- Don't edit this file: edit that, then run `python3 tools/make_tools.py`.
--[[
  FSUtility.lua  -  "FS Utility": looks after the other FS tools in the show
  ------------------------------------------------------------------------
  Run it (click it in the Plugins pool) and pick one of:

  - Reimport from console: imports every FS tool's XML found in the console's plugins folder
    (gma3_library/datapools/plugins) into the Plugins pool. A tool already in the pool is replaced in
    its own slot; a new one goes in the first free slot. FS Utility itself is left alone (re-import it
    by hand).
  - Reimport from USB: the same from a USB stick. It looks on every drive for
    grandMA3/gma3_library/datapools/plugins, gma3_library/datapools/plugins, FireSystemMinis/ and the
    stick's top folder; type a folder in "USB folder" to use that one instead.
  - Re-run all: runs every tool that has been built in this show again, in build order (FS Presets
    first, FS Icons last), with the settings of its last run and no dialogs (each tool is called
    with the argument "rebuild": Plugin "FS LOS" "rebuild").
  - Delete all: after a confirm, deletes everything the tools made: objects named "FS <tag> ..."
    (DF, CF, CP, PP, BS, GB, LO, IC, and FS Icons' "FS ic ..." discs) in the layouts, sequences,
    macros, MAtricks, presets and appearances, FS Icons' own images (3.3101+), FS Masters' master and
    group faders, and the tools' saved settings. Two boxes, off by default, also take what the main
    FireSystem plugin shares: FS Presets' presets ("FS ..." in the preset pools) and FireSystem's
    icon discs ("FS r ..." / "FS n ..." appearances and "FS fs_..." images).

  ONE FILE: plugins/FSUtility.lua is generated from this source by tools/make_tools.py. It needs
  none of the FireSystem modules.
--]]

local TITLE = "FS Utility"

-- the tools, in build order: {plugin name, XML file, the setting that shows it was built}
local TOOLS = {
  {name = "FS Presets", file = "FSPresets.xml", built = "FSP_groups"},
  {name = "FS Dimmer FX", file = "FSDimmerFX.xml", built = "FSDF_groups"},
  {name = "FS Colour FX", file = "FSColourFX.xml", built = "FSCF_groups"},
  {name = "FS Colour Picker", file = "FSColourPicker.xml", built = "FSC_groups"},
  {name = "FS Position Picker", file = "FSPositionPicker.xml", built = "FSPP_groups"},
  {name = "FS Bumps", file = "FSBumps.xml", built = "FSBS_groups"},
  {name = "FS Gobo Beam", file = "FSGoboBeam.xml", built = "FSGB_groups"},
  {name = "FS LOS", file = "FSLOS.xml", built = "FSLO_groups"},
  {name = "FS Masters", file = "FSMasters.xml", built = "FSMS_groups"},
  {name = "FS Icons", file = "FSIcons.xml", built = "FSIC_keep"},
}
-- the tools' own name tags ("FS <tag> ...") and their global variables
local TAGS = {"DF", "CF", "CP", "PP", "BS", "GB", "LO", "IC", "ic"}
local VARPS = {"FSDF_", "FSCF_", "FSC_", "FSPP_", "FSBS_", "FSGB_", "FSLO_", "FSMS_", "FSIC_"}
local VAR_KEYS = {"groups", "layout", "seq", "macro", "ap", "mtx", "speed", "rate", "preset", "banks",
                  "step", "page", "skip", "keep"}
local ROW_VARS = {"tint", "act", "size", "sym"}   -- per-row play state: <VARP>L<layout>_g<row>_<key>
local FSP_KEYS = {"groups", "force", "dim", "col", "pos", "pfx", "strobe", "zoom", "gobo", "beam"}
local PRESET_POOLS = {1, 2, 3, 4, 5, 6, 21}
local IMAGE_POOL, MINI_IMAGES = 3, {3101, 3400}   -- FS Icons' own images
local MASTER_EXECS = {201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 409, 410}
local OPT_PRESETS = "Also FS Presets' presets"
local OPT_SHARED = "Also FireSystem's shared icon discs"

local function say(msg)
  Printf(msg)
  pcall(MessageBox, {title = TITLE, message = msg, commands = {{value = 1, name = "OK"}}})
end
local function gvar(k) local v = GetVar(GlobalVars(), k) return v end
local function obj(path)
  local ok, l = pcall(ObjectList, path)
  return ok and type(l) == "table" and l[1] or nil
end
local function field(h, a, b)
  local v
  pcall(function() v = h[a] end)
  if v == nil and b then pcall(function() v = h[b] end) end
  return v
end
local function numOf(h) return tonumber(field(h, "no", "No")) end
local function nameOf(h) local v = field(h, "name", "Name") return v and tostring(v) or nil end
local function sep()
  local s
  pcall(function() s = GetPathSeparator() end)
  return type(s) == "string" and s ~= "" and s or "/"
end
local function join(...) return (table.concat({...}, sep()):gsub("[/\\]+", sep())) end
local function exists(path)
  local f = io.open(path, "rb")
  if f then f:close() return true end
  return false
end

-- ---------------------------------------------------------------- reimport
local function libraryPath()
  local dir
  pcall(function() dir = GetPath(Enums.PathType.Library) end)
  if type(dir) ~= "string" or dir == "" then pcall(function() dir = GetPath("library") end) end
  if type(dir) ~= "string" or dir == "" then
    dir = (os.getenv("HOME") or os.getenv("USERPROFILE") or ".") .. "/MALightingTechnology/gma3_library"
  end
  return (dir:gsub("[/\\]+$", ""))
end
-- the tools' files in a folder (an XML counts when its .lua is there too)
local function filesIn(dir)
  local l = {}
  if not dir or dir == "" then return l end
  for _, tl in ipairs(TOOLS) do
    if exists(join(dir, tl.file)) and exists(join(dir, (tl.file:gsub("%.xml$", ".lua")))) then l[#l + 1] = tl end
  end
  return l
end
local function consoleDirs()
  local l = {join(libraryPath(), "datapools", "plugins")}
  pcall(function() local d = GetPath(Enums.PathType.UserPlugins) if type(d) == "string" and d ~= "" then l[#l + 1] = d end end)
  return l
end
-- every drive's likely plugin folders
local function usbDirs()
  local roots, seen = {}, {}
  local function add(p) if type(p) == "string" and p ~= "" and not seen[p] then seen[p] = true roots[#roots + 1] = p end end
  pcall(function()
    for _, d in ipairs(Root().Temp.DriveCollect:Children()) do add(field(d, "path", "Path")) end
  end)
  for _, base in ipairs({"/media", "/Volumes", "/mnt"}) do
    pcall(function()
      for _, e in ipairs(DirList(base, "*") or {}) do if e.name then add(base .. "/" .. e.name) end end
    end)
  end
  for c = ("D"):byte(), ("Z"):byte() do if sep() == "\\" then add(string.char(c) .. ":\\") end end
  local l, lib = {}, libraryPath()
  for _, r in ipairs(roots) do
    if r:gsub("[/\\]+$", "") ~= lib then
      for _, sub in ipairs({{"grandMA3", "gma3_library", "datapools", "plugins"}, {"gma3_library", "datapools", "plugins"},
                            {"FireSystemMinis"}, {}}) do
        l[#l + 1] = join(r, table.unpack(sub))
      end
    end
  end
  return l
end
local function pluginSlot(name)
  local h = obj(string.format('Plugin "%s"', name))
  if h then return numOf(h), true end
  local n = 1
  while n < 10000 and obj("Plugin " .. n) do n = n + 1 end
  return n, false
end
local function reimport(dirs, where)
  local dir, list
  for _, d in ipairs(dirs) do
    list = filesIn(d)
    if #list > 0 then dir = d break end
  end
  if not dir then
    say("No FS plugin files (FS<Tool>.xml + .lua) found " .. where .. ". Looked in:\n" ..
        (#dirs > 0 and table.concat(dirs, "\n") or "(no drives found: type the folder in USB folder)"))
    return
  end
  local done, failed = {}, {}
  for _, tl in ipairs(list) do
    local n, had = pluginSlot(tl.name)
    if had then Cmd(string.format("Delete Plugin %d /NC", n)) end
    local ok = false
    for _, c in ipairs({string.format('Import Plugin %d /File "%s" /Path "%s" /NoConfirm', n, tl.file, dir),
                        string.format('Import Plugin %d /File "%s" /Path "%s"', n, tl.file, dir)}) do
      pcall(Cmd, c)
      if obj("Plugin " .. n) then ok = true break end
    end
    if ok then done[#done + 1] = string.format("%s (Plugin %d)", tl.name, n) else failed[#failed + 1] = tl.name end
  end
  local msg = string.format("Imported from %s:\n%s", dir, #done > 0 and table.concat(done, "\n") or "nothing")
  if #failed > 0 then msg = msg .. "\n\nCould not import: " .. table.concat(failed, ", ") end
  say(msg)
end

-- ---------------------------------------------------------------- re-run
local function rerun()
  local ran = {}
  for _, tl in ipairs(TOOLS) do
    local v = gvar(tl.built)
    if v ~= nil and tostring(v) ~= "" then
      Cmd(string.format('Plugin "%s" "rebuild"', tl.name))
      ran[#ran + 1] = tl.name
    end
  end
  say(#ran > 0 and ("Ran again with their last settings:\n" .. table.concat(ran, "\n"))
      or "None of the FS tools has been built in this show yet.")
end

-- ---------------------------------------------------------------- delete
-- the numbers of the objects of a kind whose name starts with one of the prefixes
-- (kind "Preset" / "Image" take a pool: Preset 21.5)
local function named(kind, pool, prefixes, range)
  local nums, seen = {}, {}
  local function take(h)
    local n, name = numOf(h), nameOf(h)
    if not n or not name or seen[n] then return end
    if range and (n < range[1] or n > range[2]) then return end
    for _, p in ipairs(prefixes) do
      if name:sub(1, #p) == p then seen[n] = true nums[#nums + 1] = n return end
    end
  end
  for _, p in ipairs(prefixes) do
    local path = pool and string.format('%s %d."%s"*', kind, pool, p) or string.format('%s "%s"*', kind, p)
    local ok, l = pcall(ObjectList, path)
    for _, h in ipairs(ok and type(l) == "table" and l or {}) do take(h) end
  end
  pcall(function()
    local parent
    if kind == "Appearance" then parent = ShowData().Appearances
    elseif kind == "Image" then parent = ShowData().MediaPools.Images
    elseif kind == "Preset" then parent = DataPool().PresetPools[pool]
    else parent = DataPool()[kind == "MAtricks" and "MAtricks" or kind .. "s"] end
    for _, h in ipairs(parent and parent:Children() or {}) do take(h) end
  end)
  table.sort(nums)
  return nums
end
local function deleteAll(o, presets, shared)
  local own = {}
  for _, t in ipairs(TAGS) do own[#own + 1] = "FS " .. t .. " " end
  -- FS Masters' faders (playback / speed masters and group masters); the keys go with their sequences
  local pg = tonumber(gvar("FSMS_page") or "")
  if pg then
    for p = pg, pg + 2 do
      pcall(function()
        local page = DataPool().Pages[p]
        for _, e in ipairs(page and page:Children() or {}) do
          local ex = numOf(e)
          local isOurs = false
          for _, m in ipairs(MASTER_EXECS) do if m == ex then isOurs = true end end
          local held = field(e, "Object")
          local cls = held and tostring(held:GetClass()) or ""
          if isOurs and (cls:find("Master") or (cls == "Group" and ex <= 208)) then
            Cmd(string.format("Delete Page %d.%d /NC", p, ex))
            o.n = o.n + 1
          end
        end
      end)
    end
  end
  local function del(kind, pool, prefixes, range)
    for _, n in ipairs(named(kind, pool, prefixes, range)) do
      Cmd(pool and string.format("Delete %s %d.%d /NC", kind, pool, n) or string.format("Delete %s %d /NC", kind, n))
      o.n = o.n + 1
    end
  end
  for _, kind in ipairs({"Layout", "Sequence", "Macro", "MAtricks"}) do del(kind, nil, own) end
  for _, pool in ipairs(PRESET_POOLS) do del("Preset", pool, own) end
  if presets then for _, pool in ipairs(PRESET_POOLS) do del("Preset", pool, {"FS "}) end end
  del("Appearance", nil, own)
  del("Image", IMAGE_POOL, {"FS fs_"}, MINI_IMAGES)   -- (one by one: Thru doesn't work for images)
  if shared then
    del("Appearance", nil, {"FS r ", "FS n "})
    del("Image", IMAGE_POOL, {"FS fs_"})
  end
  -- the saved settings, and the pickers' per-row play state
  local vars = GlobalVars()
  for _, vp in ipairs(VARPS) do
    local L = tonumber(gvar(vp .. "layout") or "")
    if L then
      for row = 0, 21 do for _, k in ipairs(ROW_VARS) do
        pcall(DelVar, vars, string.format("%sL%d_g%d_%s", vp, L, row, k))
      end end
    end
    for _, k in ipairs(VAR_KEYS) do pcall(DelVar, vars, vp .. k) end
  end
  if presets then for _, k in ipairs(FSP_KEYS) do pcall(DelVar, vars, "FSP_" .. k) end end
end
local function confirmDelete()
  local r = MessageBox({
    title = TITLE,
    message = "Delete everything the FS tools made in this show?\n" ..
              "Layouts, sequences, macros, MAtricks, presets and appearances named FS DF / CF / CP / PP /\n" ..
              "BS / GB / LO / IC ..., FS Icons' images, FS Masters' faders and the tools' settings.\n" ..
              "The boxes below also delete what the main FireSystem plugin shares with the tools:\n" ..
              "leave them off if the show uses FireSystem itself. This can't be undone (Oops aside).",
    commands = {{value = 1, name = "Delete"}, {value = 0, name = "Cancel"}},
    states = {{name = OPT_PRESETS, state = false}, {name = OPT_SHARED, state = false}},
  })
  if not r or r.result ~= 1 then return nil end
  local s = r.states or {}
  return true, s[OPT_PRESETS] == true, s[OPT_SHARED] == true
end

-- ---------------------------------------------------------------- main
local CMD = {console = 1, usb = 2, rerun = 3, delete = 4}

local function main(displayHandle, argument)
  local r = MessageBox({
    title = TITLE,
    message = "Reimport: loads every FS tool's XML into the Plugins pool again (each in its own slot).\n" ..
              "  From console = gma3_library/datapools/plugins; from USB = the sticks' plugin folders,\n" ..
              "  or the folder typed below.\n" ..
              "Re-run all: builds every tool built in this show again, with its last settings.\n" ..
              "Delete all: deletes everything the tools made (asks first).",
    commands = {{value = CMD.console, name = "Reimport from console"}, {value = CMD.usb, name = "Reimport from USB"},
                {value = CMD.rerun, name = "Re-run all"}, {value = CMD.delete, name = "Delete all"},
                {value = 0, name = "Cancel"}},
    inputs = {{name = "USB folder", value = ""}},
  })
  if not r then return end
  local typed = tostring(r.inputs and r.inputs["USB folder"] or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if r.result == CMD.console then
    reimport(consoleDirs(), "on the console")
  elseif r.result == CMD.usb then
    if typed ~= "" then reimport({typed}, "in " .. typed) else reimport(usbDirs(), "on a USB drive") end
  elseif r.result == CMD.rerun then
    rerun()
  elseif r.result == CMD.delete then
    local go, presets, shared = confirmDelete()
    if not go then return end
    local o = {n = 0}
    deleteAll(o, presets, shared)
    say(string.format("Deleted %d objects the FS tools made, and their settings.", o.n))
  end
end

return main
